-- Additive verification-only proof v2. Production v1 functions and reads remain unchanged.
-- Only basic-discount title/input_source are display/internal metadata in this
-- version. All remaining keys (including unknown operative conditions) survive.
create function operations_private.hub_smartstore_price_facts_v2(p_price jsonb) returns jsonb
language plpgsql immutable set search_path=pg_catalog as $$
declare t jsonb; terms jsonb:='[]';
begin
 if jsonb_typeof(p_price) is distinct from 'object' or jsonb_typeof(p_price->'terms') is distinct from 'array' then raise exception 'invalid price facts';end if;
 for t in select value from jsonb_array_elements(p_price->'terms') loop
  if t->>'term_key' is distinct from 'basic' or t->>'term_type' is distinct from 'basic' then raise exception 'unsupported discount fact schema';end if;
  terms:=terms||jsonb_build_array(t-'title'-'input_source');
 end loop;
 return jsonb_set(p_price,'{terms}',terms);
end $$;
CREATE OR REPLACE FUNCTION operations_private.hub_canary_operations_v2(p_source text, p_version_id uuid, p_operations jsonb, p_serialized boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare op jsonb; facts jsonb; target jsonb; k text; v_sku text; original jsonb; links jsonb;
begin
 if current_setting('hub.qa_rollback_guard',true) is distinct from 'true' or p_source is distinct from 'smartstore' then raise exception 'v2 verification requires guarded QA transaction';end if;
 if jsonb_array_length(p_operations) not in (0,3) then raise exception 'three shared product options required';end if;
 if jsonb_typeof(p_operations) is distinct from 'array' or jsonb_array_length(p_operations)>100 or pg_column_size(p_operations)>262144 then raise exception 'invalid operation set';end if;
 if exists(select 1 from jsonb_array_elements(p_operations) x group by x->>'product_code',coalesce(x->>'option_code',''),x->>'field' having count(*)>1) then raise exception 'duplicate operation identity/field';end if;
 for op in select value from jsonb_array_elements(p_operations) loop
  v_sku:=op->>'sku';
  if v_sku is null or v_sku not in ('10000-1','10000-2','10000-3') then raise exception 'outside finite verification scope';end if;
  if op->>'field' is distinct from 'price' or op->>'provenance' is distinct from 'calculated' or op->>'proof_contract' is distinct from 'smartstore-basic-facts-v2'
   or op->'seller_facts_proof'->>'contract' is distinct from 'smartstore-basic-facts-v2'
   or op->'internal_provenance_proof'->>'contract' is distinct from 'hub-rule-provenance-v2'
   or op->'seller_facts_proof'->'target' is distinct from op->'effective_target'
   or operations_private.hub_smartstore_price_facts_v2(op->'internal_provenance_proof'->'price') is distinct from op->'effective_target'
   or op->'internal_provenance_proof'->>'generation_id' is distinct from op->>'generation_id'
   or op->'internal_provenance_proof'->>'input_fingerprint' is distinct from op->>'current_input_fingerprint'
   then raise exception 'separate facts/provenance proof mismatch';end if;
  if op->>'disposition' is distinct from 'CHANGE' or coalesce(op->>'provenance','') not in ('manual','calculated','baseline') or coalesce(op->>'field','') not in ('price','stock') or not op?'carrier_before' or not op?'baseline_before' or not op?'effective_target' then raise exception 'invalid operation contract';end if;
  if op->>'field'='price' and op->>'provenance'='baseline' then raise exception 'Rule-less baseline price cannot mutate carrier';end if;
  if op->>'field'='price' and op->>'provenance'='calculated' and (op->>'freshness' is distinct from 'fresh' or op->>'generation_id' is null) then raise exception 'inactive/stale calculated price';end if;
  if op->>'provenance'='manual' and op->>'override_id' is null then raise exception 'explicit override identity required';end if;
  -- Mutable identity/Rule/draft proof is checked at registration and frozen in the immutable plan.
  if not p_serialized then
  if op->>'provenance'='manual' and not exists(select 1 from public.operations_hub_change_queue q where q.change_id::text=op->>'override_id' and q.sellpia_sku_code=v_sku and q.source_channel=p_source and q.seller_product_code=op->>'product_code' and coalesce(q.seller_option_code,'')=coalesce(op->>'option_code','') and q.status in ('pending','validated','processing') and (
   (op->>'field'='stock' and q.field_key='sellpia_current_stock' and q.after_value=op->'effective_target') or
   (op->>'field'='price' and q.field_key='sellpia_sale_price' and (q.base_price_source='manual' or q.option_price_source='manual' or q.pricing_input_mode='final' or q.base_price_source='discount' and exists(select 1 from jsonb_array_elements(coalesce(q.price_discount_terms_after,'[]'::jsonb)) t where t->>'input_source'='manual')) and jsonb_build_object('base',q.price_base_after,'discounted',q.price_discounted_base_after,'option',q.price_option_after,'final',q.price_final_after,'terms',coalesce(q.price_discount_terms_after,'[]'::jsonb))=op->'effective_target')
  )) then raise exception 'explicit active override/target not verified';end if;
  select coalesce(jsonb_agg(z),'[]'::jsonb) into links from (
   select distinct l.product_code,coalesce(l.option_code,'') option_code from public.operations_hub_listing_components c join public.operations_hub_seller_listings l on l.listing_id=c.listing_id where c.is_active and l.is_active and c.sellpia_sku_code=v_sku and l.source_channel=p_source
   union select m.product_code,coalesce(m.option_code,'') from public.operations_hub_manual_links m where m.sellpia_sku_code=v_sku and m.source_channel=p_source
   union select to_jsonb(c)->>(p_source||'_product_code'),coalesce(to_jsonb(c)->>(p_source||'_option_code'),'') from operations_private.operations_hub_matrix_export_cache c where c.sellpia_sku_code=v_sku and coalesce(to_jsonb(c)->>(p_source||'_product_code'),'')<>''
  ) z;
  if jsonb_array_length(links)<>1 or links->0->>'product_code' is distinct from op->>'product_code' or links->0->>'option_code' is distinct from coalesce(op->>'option_code','') then raise exception 'canary identity missing/conflict';end if;
  if op->>'field'='price' and op->>'provenance'='calculated' and not exists(
   select 1 from operations_private.hub_calculated_results cr where cr.sku=v_sku and cr.scope=p_source and cr.field='platform_final_price' and cr.status='calculated' and cr.error is null and cr.generation_id::text=op->>'generation_id'
   and cr.value=(op->'effective_target'->>'final')::numeric
   and coalesce(cr.result_details->'discount_terms','[]'::jsonb)=op->'internal_provenance_proof'->'price'->'terms'
   and cr.rule_versions=op->'internal_provenance_proof'->'rule_versions'
   and operations_private.hub_input_fingerprint_v1(v_sku,p_source)=op->>'current_input_fingerprint'
   and coalesce(cr.result_details->>'input_fingerprint','')<>'' and cr.result_details->>'input_fingerprint'=op->>'current_input_fingerprint'
   and exists(select 1 from operations_private.hub_rule_assignments a join operations_private.hub_rules r on r.id=a.rule_id where a.sku=v_sku and a.scope=p_source and r.is_active and r.scope=a.scope and r.target_field=a.target_field and a.target_field in ('platform_registration_price','platform_discount_price','platform_option_price','platform_final_price','platform_price'))
   and operations_private.hub_rule_lineage_valid_v1(v_sku,p_source,cr.rule_versions)
   and not exists(select 1 from (values ('platform_registration_price','base'),('platform_discount_price','discounted'),('platform_option_price','option')) f(field,key) where not exists(select 1 from operations_private.hub_calculated_results part where part.sku=v_sku and part.scope=p_source and part.field=f.field and part.status='calculated' and part.error is null and part.generation_id=cr.generation_id and part.result_details->>'input_fingerprint'=cr.result_details->>'input_fingerprint' and part.value=(op->'effective_target'->>f.key)::numeric and operations_private.hub_rule_lineage_valid_v1(v_sku,p_source,part.rule_versions)))
  ) then raise exception 'active calculated generation/fingerprint not verified';end if;
  end if;
  select b.facts into facts from operations_private.hub_baseline_rows b where b.version_id=p_version_id and b.product_code=op->>'product_code' and b.option_code=coalesce(op->>'option_code','');
  if not found then raise exception 'baseline unavailable';end if;
  original:=facts->(op->>'field');target:=op->'effective_target';
  if original is null or original='null'::jsonb or original is distinct from op->'baseline_before' then raise exception 'baseline before mismatch';end if;
  if op->>'provenance'='baseline' and target is distinct from original then raise exception 'baseline provenance target mismatch';end if;
  if op->'carrier_before' is null or op->'carrier_before'='null'::jsonb then raise exception 'carrier before unavailable';end if;
  if p_serialized and target is distinct from op->'serialized_after' then raise exception 'serialized after/target mismatch';end if;
  if op->>'field'='stock' then
   if jsonb_typeof(target) is distinct from 'number' then raise exception 'stock must be integer';end if;
   if target::text::numeric<0 or target::text::numeric<>trunc(target::text::numeric) or target::text::numeric>9007199254740991 then raise exception 'stock out of range';end if;
  else
   if jsonb_typeof(target) is distinct from 'object' or jsonb_typeof(target->'terms') is distinct from 'array' then raise exception 'price tuple incomplete';end if;
   foreach k in array array['base','discounted','option','final'] loop
    if jsonb_typeof(target->k) is distinct from 'number' then raise exception 'price component missing';end if;
    if (target->>k)::numeric<>trunc((target->>k)::numeric) or abs((target->>k)::numeric)>9007199254740991 or (k<>'option' and (target->>k)::numeric<0) then raise exception 'price out of range';end if;
   end loop;
   if (target->>'discounted')::numeric+(target->>'option')::numeric<>(target->>'final')::numeric then raise exception 'price tuple inconsistent';end if;
  end if;
 end loop;
 return coalesce((select jsonb_agg(x-'serialized_after' order by x->>'product_code',coalesce(x->>'option_code',''),x->>'field') from jsonb_array_elements(p_operations) x),'[]'::jsonb);
end $function$
;
CREATE OR REPLACE FUNCTION operations_private.hub_baseline_artifact_seal_v2(p_session_token text, p_plan_id uuid, p_plan_token text, p_artifact_digest text, p_artifact_base64 text, p_file_name text, p_applied_operations jsonb, p_serializer_success boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET statement_timeout TO '30s'
AS $function$
declare who text; plan operations_private.hub_baseline_export_plans%rowtype; receipt operations_private.hub_baseline_artifact_receipts%rowtype; bytes bytea; ops jsonb;
begin
 if current_setting('hub.qa_rollback_guard',true) is distinct from 'true' then raise exception 'v2 verification requires guarded QA transaction';end if;
 who:=operations_private.require_operations_hub_operator_session(p_session_token)->>'username';
 select * into plan from operations_private.hub_baseline_export_plans where id=p_plan_id for update;
 if not found or plan.operator<>who or plan.plan_token_hash is distinct from encode(extensions.digest(p_plan_token,'sha256'),'hex') then raise exception 'invalid plan token/operator';end if;
 if p_serializer_success is distinct from true or plan.blocked_count<>0 or p_artifact_base64 is null or length(p_artifact_base64)>11184812 or length(coalesce(p_file_name,'')) not between 1 and 256 then raise exception 'serializer failed/BLOCK/artifact invalid';end if;
 bytes:=decode(p_artifact_base64,'base64');
 if octet_length(bytes) not between 1 and 8388608 or p_artifact_digest is distinct from encode(extensions.digest(bytes,'sha256'),'hex') then raise exception 'artifact digest mismatch';end if;
 ops:=operations_private.hub_canary_operations_v2(plan.source,plan.expected_version_id,p_applied_operations,true);
 if ops is distinct from plan.operations then raise exception 'serializer operation set mismatch';end if;
 select * into receipt from operations_private.hub_baseline_artifact_receipts where plan_id=p_plan_id;
 if found then
  if receipt.artifact_digest<>p_artifact_digest or receipt.artifact_bytes<>bytes or receipt.file_name<>p_file_name or receipt.applied_operations<>p_applied_operations then raise exception 'sealed artifact immutable mismatch';end if;
 else
  insert into operations_private.hub_baseline_artifact_receipts(plan_id,artifact_digest,artifact_bytes,file_name,applied_operations,serializer_success,operator) values(p_plan_id,p_artifact_digest,bytes,p_file_name,p_applied_operations,true,who);
  update public.operations_hub_export_jobs set status='ready',phase='platform_upload_pending',processed_count=jsonb_array_length(ops),updated_at=clock_timestamp(),completed_at=clock_timestamp() where job_id=plan.export_job_id;
 end if;
 return jsonb_build_object('plan_id',p_plan_id,'export_job_id',plan.export_job_id,'artifact_digest',p_artifact_digest,'operation_count',jsonb_array_length(ops),'status','platform_upload_pending');
end $function$
;
CREATE OR REPLACE FUNCTION operations_private.hub_baseline_confirm_plan_v2(p_session_token text, p_request_id uuid, p_source text, p_export_job_id uuid, p_artifact_digest text, p_expected_version_id uuid, p_expected_version integer, p_plan_token text, p_operations jsonb, p_upload_confirmed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET lock_timeout TO '5s'
 SET statement_timeout TO '60s'
AS $function$
declare who text; plan operations_private.hub_baseline_export_plans%rowtype; receipt operations_private.hub_baseline_artifact_receipts%rowtype; prior operations_private.hub_baseline_commits%rowtype; head uuid; number integer; new_id uuid; ops jsonb;
begin
 if current_setting('hub.qa_rollback_guard',true) is distinct from 'true' then raise exception 'v2 verification requires guarded QA transaction';end if;
 who:=operations_private.require_operations_hub_operator_session(p_session_token)->>'username';
 if p_request_id is null or p_upload_confirmed is distinct from true then raise exception 'explicit upload confirmation required';end if;
 perform pg_advisory_xact_lock(hashtextextended('hub-baseline-commit:'||p_request_id,0));
 select * into plan from operations_private.hub_baseline_export_plans where export_job_id=p_export_job_id;
 if not found or plan.operator<>who or (plan.source,plan.expected_version_id,plan.expected_version) is distinct from (p_source,p_expected_version_id,p_expected_version) or plan.plan_token_hash is distinct from encode(extensions.digest(p_plan_token,'sha256'),'hex') or plan.blocked_count<>0 then raise exception 'invalid plan token/version/operator or BLOCK';end if;
 perform pg_advisory_xact_lock(hashtextextended('hub-baseline-plan-commit:'||plan.id,0));
 select * into receipt from operations_private.hub_baseline_artifact_receipts where plan_id=plan.id;
 if not found or not receipt.serializer_success or receipt.artifact_digest is distinct from p_artifact_digest or receipt.applied_operations is distinct from p_operations then raise exception 'sealed serializer receipt mismatch';end if;
 ops:=operations_private.hub_canary_operations_v2(p_source,p_expected_version_id,p_operations,true);
 if ops is distinct from plan.operations then raise exception 'commit operation set mismatch';end if;
 select * into prior from operations_private.hub_baseline_commits where request_id=p_request_id;
 if found and prior.plan_id<>plan.id then raise exception 'request id reused for another export job';end if;
 if not found then select * into prior from operations_private.hub_baseline_commits where plan_id=plan.id;end if;
 if found then
  if prior.plan_id<>plan.id or prior.operator<>who then raise exception 'export job/request already committed with other identity';end if;
  return jsonb_build_object('version_id',prior.new_version_id,'previous_version_id',prior.previous_version_id,'version',(select version from operations_private.hub_baseline_versions where id=prior.new_version_id),'reused',true,'committed_request_id',prior.request_id,'operation_count',prior.operation_count);
 end if;
 select h.current_version_id,v.version into head,number from operations_private.hub_baseline_heads h join operations_private.hub_baseline_versions v on v.id=h.current_version_id where h.source=p_source for update of h;
 if head is distinct from p_expected_version_id or number is distinct from p_expected_version then raise exception 'stale baseline CAS conflict';end if;
 if jsonb_array_length(ops)=0 then new_id:=head;
 else
  insert into operations_private.hub_baseline_versions(source,version,previous_version_id,export_job_id,request_id,event,operation_count,confirmed_at,created_by) values(p_source,number+1,head,p_export_job_id,p_request_id,'confirmed_plan',jsonb_array_length(ops),clock_timestamp(),who) returning id into new_id;
  insert into operations_private.hub_baseline_rows(version_id,product_code,option_code,facts,source_row_no,source_file_name)
  select new_id,b.product_code,b.option_code,jsonb_set(jsonb_set(b.facts,'{stock}',coalesce((select x->'effective_target' from jsonb_array_elements(ops) x where x->>'product_code'=b.product_code and coalesce(x->>'option_code','')=b.option_code and x->>'field'='stock'),b.facts->'stock')),'{price}',coalesce((select x->'effective_target' from jsonb_array_elements(ops) x where x->>'product_code'=b.product_code and coalesce(x->>'option_code','')=b.option_code and x->>'field'='price'),b.facts->'price')),b.source_row_no,b.source_file_name from operations_private.hub_baseline_rows b where b.version_id=head;
  update operations_private.hub_baseline_heads set current_version_id=new_id where source=p_source and current_version_id=head;
  if not found then raise exception 'baseline CAS conflict';end if;
 end if;
 insert into operations_private.hub_baseline_commits(request_id,plan_id,previous_version_id,new_version_id,artifact_digest,operation_count,operator) values(p_request_id,plan.id,head,new_id,p_artifact_digest,jsonb_array_length(ops),who);
 update public.operations_hub_export_jobs set phase='baseline_committed',updated_at=clock_timestamp(),snapshot=coalesce(snapshot,'{}'::jsonb)||jsonb_build_object('baseline_version_id',new_id,'baseline_confirmed_at',clock_timestamp()) where job_id=plan.export_job_id;
 return jsonb_build_object('version_id',new_id,'previous_version_id',head,'version',case when new_id=head then number else number+1 end,'reused',false,'operation_count',jsonb_array_length(ops));
end $function$
;
CREATE OR REPLACE FUNCTION operations_private.hub_baseline_plan_register_v2(p_session_token text, p_request_id uuid, p_source text, p_expected_version_id uuid, p_expected_version integer, p_carrier_digest text, p_operations jsonb, p_warning_count integer, p_blocked_count integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET lock_timeout TO '5s'
 SET statement_timeout TO '30s'
AS $function$
declare who text; ops jsonb; existing operations_private.hub_baseline_export_plans%rowtype; head uuid; number integer; token text; job uuid; pid uuid;
begin
 if current_setting('hub.qa_rollback_guard',true) is distinct from 'true' then raise exception 'v2 verification requires guarded QA transaction';end if;
 who:=operations_private.require_operations_hub_operator_session(p_session_token)->>'username';
 if p_request_id is null or p_source not in ('smartstore','makeshop','ably') or p_source is null or p_expected_version_id is null or p_expected_version is null or p_carrier_digest !~ '^[0-9a-f]{64}$' or p_carrier_digest is null or p_warning_count is null or p_warning_count<0 or p_blocked_count is distinct from 0 then raise exception 'invalid or BLOCK plan';end if;
 perform pg_advisory_xact_lock(hashtextextended('hub-baseline-plan:'||p_request_id,0));
 if jsonb_typeof(p_operations) is distinct from 'array' or jsonb_array_length(p_operations)>100 or pg_column_size(p_operations)>262144 then raise exception 'invalid bounded operations';end if;
 ops:=coalesce((select jsonb_agg(x-'serialized_after' order by x->>'product_code',coalesce(x->>'option_code',''),x->>'field') from jsonb_array_elements(p_operations) x),'[]'::jsonb);
 select * into existing from operations_private.hub_baseline_export_plans where request_id=p_request_id;
 if found then
  if (existing.source,existing.expected_version_id,existing.expected_version,existing.carrier_digest,existing.operations,existing.warning_count,existing.operator) is distinct from (p_source,p_expected_version_id,p_expected_version,p_carrier_digest,ops,p_warning_count,who) then raise exception 'plan request id reused with different inputs';end if;
  token:=existing.plan_token;
  return jsonb_build_object('plan_id',existing.id,'export_job_id',existing.export_job_id,'plan_token',token,'reused',true);
 end if;
 ops:=operations_private.hub_canary_operations_v2(p_source,p_expected_version_id,p_operations);
 select h.current_version_id,v.version into head,number from operations_private.hub_baseline_heads h join operations_private.hub_baseline_versions v on v.id=h.current_version_id where h.source=p_source for update of h;
 if head is distinct from p_expected_version_id or number is distinct from p_expected_version then raise exception 'stale baseline head/version';end if;
 insert into public.operations_hub_export_jobs(source_channel,requested_by,selected_skus,status,phase,total_count,snapshot) values(p_source,who,array(select distinct x->>'sku' from jsonb_array_elements(ops) x),'running','baseline_canary',jsonb_array_length(ops),jsonb_build_object('canary',true)) returning job_id into job;
 pid:=gen_random_uuid();token:=encode(extensions.gen_random_bytes(32),'hex');
 insert into operations_private.hub_baseline_export_plans(id,request_id,source,export_job_id,expected_version_id,expected_version,plan_token_hash,plan_token,carrier_digest,operations,warning_count,blocked_count,operator) values(pid,p_request_id,p_source,job,p_expected_version_id,p_expected_version,encode(extensions.digest(token,'sha256'),'hex'),token,p_carrier_digest,ops,p_warning_count,0,who);
 return jsonb_build_object('plan_id',pid,'export_job_id',job,'plan_token',token,'reused',false);
end $function$
;
CREATE OR REPLACE FUNCTION public.hub_baseline_artifact_seal_v2(p_session_token text, p_plan_id uuid, p_plan_token text, p_artifact_digest text, p_artifact_base64 text, p_file_name text, p_applied_operations jsonb, p_serializer_success boolean)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO 'pg_catalog'
AS $function$select operations_private.hub_baseline_artifact_seal_v2(p_session_token,p_plan_id,p_plan_token,p_artifact_digest,p_artifact_base64,p_file_name,p_applied_operations,p_serializer_success);$function$
;
CREATE OR REPLACE FUNCTION public.hub_baseline_confirm_plan_v2(p_session_token text, p_request_id uuid, p_source text, p_export_job_id uuid, p_artifact_digest text, p_expected_version_id uuid, p_expected_version integer, p_plan_token text, p_operations jsonb, p_upload_confirmed boolean)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO 'pg_catalog'
AS $function$select operations_private.hub_baseline_confirm_plan_v2(p_session_token,p_request_id,p_source,p_export_job_id,p_artifact_digest,p_expected_version_id,p_expected_version,p_plan_token,p_operations,p_upload_confirmed);$function$
;
CREATE OR REPLACE FUNCTION public.hub_baseline_plan_register_v2(p_session_token text, p_request_id uuid, p_source text, p_expected_version_id uuid, p_expected_version integer, p_carrier_digest text, p_operations jsonb, p_warning_count integer, p_blocked_count integer)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO 'pg_catalog'
AS $function$select operations_private.hub_baseline_plan_register_v2(p_session_token,p_request_id,p_source,p_expected_version_id,p_expected_version,p_carrier_digest,p_operations,p_warning_count,p_blocked_count);$function$
;
do $$
declare f record;
begin
 for f in select p.oid,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','operations_private') and p.proname in ('hub_smartstore_price_facts_v2','hub_canary_operations_v2','hub_baseline_plan_register_v2','hub_baseline_artifact_seal_v2','hub_baseline_confirm_plan_v2') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.oid::regprocedure);
  if f.nspname='public' then execute format('grant execute on function %s to anon,authenticated',f.oid::regprocedure);end if;
 end loop;
end $$;
notify pgrst,'reload schema';
